question.answer:
package main

func newWarehouse(shelves int) []string {
	return make([]string, 0, shelves)
}

func store(stock []string, boxes ...string) []string {
	return append(stock, boxes...)
}

func spare(stock []string) int {
	return cap(stock) - len(stock)
}

