question.answer:
package main

func cut(deck []string, at int) ([]string, []string) {
	return deck[:at], deck[at:]
}

func deal(deck []string, hands, size int) [][]string {
	out := make([][]string, hands)
	for i := range hands {
		out[i] = deck[i*size : (i+1)*size]
	}
	return out
}

func reveal(hand []string, n int) []string {
	return hand[:n]
}

testcode.text:
deck := []string{"A", "K", "Q", "J", "10", "9", "8", "7"}
hands := deal(deck, 2, 2)
fmt.Println(reveal(hands[0], 4), len(hands[1]), cap(hands[1]), len(deal(deck, 0, 2)))
